module.exports = {
  apps: [
    {
      name: '${w}',
      script: 'node_modules/vite/bin/vite.js',
      args: 'preview --port ${x} --host 0.0.0.0',
      instances: 'max',
      exec_mode: 'cluster',
      env: {
        NODE_ENV: 'production',
        PORT: '${x}'
      }
    }
  ]
};

